import React, { useState, useEffect } from 'react';
import { db, auth } from './firebase'; // adjust these imports based on your Firebase config
import { collection, query, where, orderBy, getDocs } from 'firebase/firestore';
import { Row, Col, Accordion } from 'react-bootstrap';
import { Line } from 'react-chartjs-2';
import 'chart.js/auto';
import { format } from 'date-fns';

// Helper: Capitalize each word.
const capitalizeWords = (str) =>
  str.replace(/\b\w/g, (match) => match.toUpperCase());

const FuturePredictions= () => {
  const [predictions, setPredictions] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Simple linear regression (least-squares)
  const linearRegression = (x, y) => {
    const n = x.length;
    const sumX = x.reduce((a, b) => a + b, 0);
    const sumY = y.reduce((a, b) => a + b, 0);
    const sumXY = x.reduce((acc, cur, i) => acc + cur * y[i], 0);
    const sumX2 = x.reduce((acc, cur) => acc + cur * cur, 0);
    const denominator = n * sumX2 - sumX * sumX;
    if (denominator === 0) return { slope: 0, intercept: 0 };
    const slope = (n * sumXY - sumX * sumY) / denominator;
    const intercept = (sumY - slope * sumX) / n;
    return { slope, intercept };
  };

  useEffect(() => {
    const fetchWorkouts = async () => {
      try {
        const user = auth.currentUser;
        if (!user) {
          setError('User not logged in');
          setLoading(false);
          return;
        }
        // Query workouts for the current user, ordered by timestamp ascending.
        const q = query(
          collection(db, 'workouts'),
          where('uid', '==', user.uid),
          orderBy('timestamp', 'asc')
        );
        const querySnapshot = await getDocs(q);
        const workouts = querySnapshot.docs.map((doc) => doc.data());
        if (workouts.length === 0) {
          setError('No workouts found for this user');
          setLoading(false);
          return;
        }

        // Determine the global start date from the earliest workout.
        let globalStart = new Date(workouts[0].timestamp.seconds * 1000);
        workouts.forEach((w) => {
          const t = new Date(w.timestamp.seconds * 1000);
          if (t < globalStart) globalStart = t;
        });

        // "Explode" workouts: convert each workout's exercises array into individual records.
        let exploded = [];
        workouts.forEach((workout) => {
          const workoutDate = new Date(workout.timestamp.seconds * 1000);
          const days_since_start = Math.floor(
            (workoutDate - globalStart) / (1000 * 60 * 60 * 24)
          );
          if (Array.isArray(workout.exercises)) {
            workout.exercises.forEach((ex) => {
              if (
                ex.exercise &&
                ex.weight !== undefined &&
                Array.isArray(ex.reps)
              ) {
                const validReps = ex.reps
                  .map((r) => parseFloat(r))
                  .filter((r) => !isNaN(r));
                const avgReps =
                  validReps.length > 0
                    ? validReps.reduce((a, b) => a + b, 0) / validReps.length
                    : null;
                exploded.push({
                  exercise: ex.exercise,
                  reps: avgReps,
                  weight: parseFloat(ex.weight),
                  timestamp: workoutDate,
                  days_since_start: days_since_start,
                });
              }
            });
          }
        });

        // Group records by normalized exercise name.
        const groups = {};
        exploded.forEach((item) => {
          const name = item.exercise.toLowerCase().trim();
          if (!groups[name]) groups[name] = [];
          groups[name].push(item);
        });

        // For each exercise, compute historical data and future predictions.
        const predictionsObj = {};
        Object.keys(groups).forEach((exName) => {
          let dataArr = groups[exName].filter(
            (item) => item.weight != null && item.reps != null
          );
          if (dataArr.length < 2) return; // Skip if insufficient data.
          // Sort by days_since_start.
          dataArr.sort((a, b) => a.days_since_start - b.days_since_start);

          // Historical data: take the last 7 data points.
          const hist = dataArr.slice(-7);
          const histDates = hist.map((item) =>
            format(item.timestamp, 'yyyy-MM-dd')
          );
          const histWeights = hist.map((item) => item.weight);

          // Future predictions: use the last 5 points to perform linear regression.
          const recent = dataArr.slice(-5);
          const xRecent = recent.map((item) => item.days_since_start);
          const yRecent = recent.map((item) => item.weight);
          const { slope } = linearRegression(xRecent, yRecent);
          const nonNegSlope = Math.max(0, slope);

          // Now, instead of predicting every calendar day, account for workout frequency.
          const firstDay = dataArr[0].days_since_start;
          const lastDay = dataArr[dataArr.length - 1].days_since_start;
          const lastWeight = dataArr[dataArr.length - 1].weight;
          // Compute average interval (in days) between workouts.
          const avgInterval =
            (lastDay - firstDay) / (dataArr.length - 1) || 1;
          // Determine how many future workout sessions are expected in the next 14 calendar days.
          const numSessions = Math.ceil(14 / avgInterval);
          let futureDays = [];
          let futurePredictions = [];
          for (let i = 1; i <= numSessions; i++) {
            // Predicted day (as calendar day index) is lastDay + (i * avgInterval)
            const predictedDay = lastDay + i * avgInterval;
            futureDays.push(predictedDay);
            // Predict using the per-workout improvement:
            // Improvement per workout = nonNegSlope * avgInterval.
            futurePredictions.push(lastWeight + i * (nonNegSlope * avgInterval));
          }
          // Convert future day indices back to dates.
          const futureDates = futureDays.map((d) => {
            const date = new Date(globalStart.getTime() + d * 24 * 60 * 60 * 1000);
            return format(date, 'yyyy-MM-dd');
          });

          predictionsObj[exName] = {
            historical: { dates: histDates, weights: histWeights },
            future: { dates: futureDates, predictions: futurePredictions },
          };
        });
        setPredictions(predictionsObj);
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    fetchWorkouts();
  }, []);

  if (loading) return <div>Loading predictions...</div>;
  if (error) return <div>Error: {error}</div>;
  if (!Object.keys(predictions).length)
    return <div>No prediction data available</div>;

  // Chart options (colors kept the same as your original sample).
  const chartOptions = {
    scales: {
      x: {
        title: { display: true, text: 'Date' },
        type: 'time',
        time: {
          unit: 'day',
          tooltipFormat: 'yyyy-MM-dd',
          displayFormats: { day: 'yyyy-MM-dd' },
        },
      },
      y: {
        title: { display: true, text: 'Weight (lbs)' },
      },
    },
    plugins: { legend: { display: true } },
  };

  return (
    <div>
      <h1>Future Predictions for All Exercises</h1>
      <Accordion defaultActiveKey="0" alwaysOpen>
        <Row xs={1} md={2} lg={3} className="g-4" style={{ marginTop: '20px' }}>
          {Object.keys(predictions).map((exName, index) => {
            const pred = predictions[exName];
            // Combine historical and future data for charting.
            const chartLabels = [
              ...pred.historical.dates,
              ...pred.future.dates,
            ];
            const chartData = [
              ...pred.historical.weights,
              ...pred.future.predictions,
            ];
            const dataConfig = {
              labels: chartLabels,
              datasets: [
                {
                  label: `${capitalizeWords(exName)} Weight`,
                  data: chartData,
                  fill: false,
                  borderColor: 'rgba(75,192,192,1)',
                  backgroundColor: 'rgba(75,192,192,0.2)',
                },
              ],
            };
            return (
              <Col key={exName}>
                <Accordion.Item eventKey={String(index)}>
                  <Accordion.Header>
                    {capitalizeWords(exName)} Performance
                  </Accordion.Header>
                  <Accordion.Body>
                    <Line data={dataConfig} options={chartOptions} />
                  </Accordion.Body>
                </Accordion.Item>
              </Col>
            );
          })}
        </Row>
      </Accordion>
    </div>
  );
};

export default FuturePredictions;
