// src/Recommendations.js
import React, { useState, useEffect } from 'react';
import { Badge, Spinner, Alert, Card, Row, Col } from 'react-bootstrap';
import ReactMarkdown from 'react-markdown';
import { db, auth } from './firebase';
import { doc, getDoc, collection, query, where, orderBy, getDocs, addDoc } from 'firebase/firestore';

async function fetchWorkoutData() {
  // Retrieve all workouts for current user
  const user = auth.currentUser;
  if (!user) return [];
  try {
    const workoutsRef = collection(db, 'workouts');
    const q = query(workoutsRef, where('uid', '==', user.uid), orderBy('timestamp', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
  } catch (error) {
    console.error("Error fetching workouts:", error);
    return [];
  }
}

async function fetchProfileData() {
  const user = auth.currentUser;
  if (!user) return null;
  const profileSnap = await getDoc(doc(db, 'profiles', user.uid));
  return profileSnap.exists() ? profileSnap.data() : null;
}

async function fetchChatGPT(prompt) {
  const response = await fetch('https://us-central1-workout-tracker-9d1ec.cloudfunctions.net/chatCompletion', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ prompt })
  });
  const data = await response.json();
  return data.completion;
}

const Recommendations = () => {
  const [aiRecommendation, setAiRecommendation] = useState('');
  const [savedRecommendations, setSavedRecommendations] = useState([]);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  // Fetch saved recommendations on component mount
  useEffect(() => {
    const fetchSavedRecommendations = async () => {
      setLoading(true);
      try {
        const user = auth.currentUser;
        if (!user) return;
        
        const recRef = collection(db, 'recommendations');
        const q = query(recRef, where('uid', '==', user.uid), orderBy('timestamp', 'desc'));
        const snapshot = await getDocs(q);
        const recs = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setSavedRecommendations(recs);
      } catch (err) {
        console.error(err);
        setErrorMessage('Failed to fetch saved recommendations.');
      } finally {
        setLoading(false);
      }
    };
    fetchSavedRecommendations();
  }, []);

  const handlePlanClick = async (planType) => {
    setLoading(true);
    setErrorMessage('');
    try {
      const workouts = await fetchWorkoutData();
      const profile = await fetchProfileData();

      const workoutSummary = workouts.slice(0, 5).map(w => ({
        splitDay: w.splitDay,
        exercises: w.exercises,
        quality: w.quality
      }));
      const summary = `User Profile: ${JSON.stringify(profile)}. Recent Workouts: ${JSON.stringify(workoutSummary)}.`;

      let prompt = '';
      if (planType === 'pre-workout') {
        prompt = `${summary} Based on this data, recommend a pre-workout plan: what to eat and which supplements to take and when.`;
      } else if (planType === 'workout') {
        prompt = `${summary} Based on this data, suggest a workout plan for today with exercise order, sets, and reps to maximize gains and minimize fatigue.`;
      } else if (planType === 'post-workout') {
        prompt = `${summary} Based on this data, provide a post-workout plan: what to eat and which supplements to take.`;
      }

      const recommendation = await fetchChatGPT(prompt);
      setAiRecommendation(recommendation);

      const user = auth.currentUser;
      if (user) {
        const recRef = collection(db, 'recommendations');
        const newRec = {
          uid: user.uid,
          type: planType,
          content: recommendation,
          timestamp: new Date()
        };
        const docRef = await addDoc(recRef, newRec);
        setSavedRecommendations(prev => [{ id: docRef.id, ...newRec }, ...prev]);
      }
    } catch (error) {
      console.error(error);
      setErrorMessage('Failed to fetch recommendation.');
    } finally {
      setLoading(false);
    }
  };

  function getExerciseDisplay(exercise, workoutType) {
    if (workoutType === 'Swimming') {
      let text = `Swimming - ${exercise.swimDistance || 0} meters`;
      if (exercise.swimFeel) text += ` - ${exercise.swimFeel}`;
      if (exercise.feltDizzy) text += ` (Dizzy)`;
      if (exercise.strokesUsed?.length) {
        text += ` | Strokes: ${exercise.strokesUsed.join(', ')}`;
      }
      return text;
    } else if (workoutType === 'Cardio') {
      const durationText = exercise.duration ? `${exercise.duration} minutes` : '';
      const distanceText = exercise.distance ? `${exercise.distance} miles` : '';
      return `${exercise.exercise} - ${durationText} ${distanceText}`;
    } else {
      return `${exercise.exercise} - ${exercise.weight || 0} lbs - ${exercise.sets || 0} sets - ${
        exercise.reps?.join(', ') || '0'
      } reps`;
    }
  }

  return (
    <div>
      <h2>Recommendations</h2>
      <Badge pill bg="primary" style={{ cursor: 'pointer', marginRight: '10px' }} onClick={() => handlePlanClick('pre-workout')}>
        Pre-Workout Plan
      </Badge>
      <Badge pill bg="secondary" style={{ cursor: 'pointer', marginRight: '10px' }} onClick={() => handlePlanClick('workout')}>
        Workout Plan
      </Badge>
      <Badge pill bg="success" style={{ cursor: 'pointer' }} onClick={() => handlePlanClick('post-workout')}>
        Post-Workout Plan
      </Badge>

      {loading && <Spinner animation="border" />}
      {errorMessage && <Alert variant="danger">{errorMessage}</Alert>}

      {/* Display newly fetched AI recommendation in Markdown */}
      {aiRecommendation && (
        <div style={{ marginTop: '20px' }}>
          <h4>Latest AI Recommendation:</h4>
          <ReactMarkdown>{aiRecommendation}</ReactMarkdown>
        </div>
      )}

      {/* Display saved recommendations as tiles/cards */}
      <div style={{ marginTop: '40px' }}>
        <h3>Your Saved Recommendations</h3>
        <Row xs={1} md={2} lg={3} className="g-4">
          {savedRecommendations.map(rec => (
            <Col key={rec.id}>
              <Card>
                <Card.Body>
                  <Card.Title>{rec.type.replace('-', ' ').toUpperCase()}</Card.Title>
                  <Card.Subtitle className="mb-2 text-muted">
                    {new Date(rec.timestamp).toLocaleDateString()}
                  </Card.Subtitle>
                  <Card.Text>
                    <ReactMarkdown>{rec.content}</ReactMarkdown>
                  </Card.Text>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      </div>
    </div>
  );
};

export default Recommendations;
